import java.util.*;

// Insertion order required -> LinkedHashMap
Map<String, Integer> ordered = new LinkedHashMap<>();
ordered.put("alice", 90);
ordered.put("bob", 85);
ordered.put("carol", 95);
ordered.forEach((k, v) -> System.out.println(k + "=" + v));
// alice=90, bob=85, carol=95  (exact insertion order)

// Sorted keys + range queries -> TreeMap
TreeMap<String, Integer> sorted = new TreeMap<>(ordered);
System.out.println(sorted.firstKey());          // alice (sorted)
System.out.println(sorted.headMap("carol"));     // {alice=90, bob=85}
```

Use HashMap only when iteration order is irrelevant; reach for LinkedHashMap or TreeMap the moment order or ranges matter.

import java.util.LinkedHashMap;
import java.util.Map;

class LRUCache<K, V> extends LinkedHashMap<K, V> {
    private final int capacity;

    public LRUCache(int capacity) {
        super(capacity, 0.75f, true);  // accessOrder=true is key
        this.capacity = capacity;
    }

    @Override
    protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
        return size() > capacity;  // evict when over capacity
    }
}

var cache = new LRUCache<String, String>(3);
cache.put("user:1", "Alice");
cache.put("user:2", "Bob");
cache.put("user:3", "Charlie");
cache.get("user:1");  // moves user:1 to end (most recent)
cache.put("user:4", "Diana");  // evicts user:2 (least recent)
System.out.println(cache.containsKey("user:2"));  // false

import java.time.LocalDateTime;
import java.util.Map;
import java.util.TreeMap;

record Event(String name, String location) {}

var schedule = new TreeMap<LocalDateTime, Event>();
schedule.put(LocalDateTime.of(2024, 1, 15, 9, 0), new Event("Standup", "Room A"));
schedule.put(LocalDateTime.of(2024, 1, 15, 14, 0), new Event("Review", "Room B"));
schedule.put(LocalDateTime.of(2024, 1, 15, 16, 30), new Event("Planning", "Room C"));

var now = LocalDateTime.of(2024, 1, 15, 15, 0);
var nextEventTime = schedule.ceilingKey(now);  // 16:30 Planning
var lastEventTime = schedule.floorKey(now);    // 14:00 Review

var morningEvents = schedule.headMap(LocalDateTime.of(2024, 1, 15, 12, 0));  // before noon
var afternoonEvents = schedule.tailMap(LocalDateTime.of(2024, 1, 15, 13, 0));  // after 1pm

var workHours = schedule.subMap(
    LocalDateTime.of(2024, 1, 15, 9, 0),
    LocalDateTime.of(2024, 1, 15, 17, 0)  // 9am to 5pm range
);

