var orderCounts = new HashMap<String, Integer>();
var orders = List.of("ORDER-1", "ORDER-2", "ORDER-1", "ORDER-3", "ORDER-1");

for (var orderId : orders) {
    orderCounts.merge(orderId, 1, Integer::sum);  // elegant frequency counting
}
System.out.println(orderCounts);  // {ORDER-1=3, ORDER-2=1, ORDER-3=1}

